<template><el-card><template #header>消息配置</template><el-alert v-if="error" :title="error" type="error" show-icon/><el-empty v-else-if="!loading&&!rows.length" description="暂无消息配置"/><el-table v-else :data="rows" v-loading="loading"><el-table-column prop="templateNo" label="模板编码"/><el-table-column label="通知渠道"><template #default="s">{{ Array.isArray(s.row.channels)&&s.row.channels.length?s.row.channels.join('、'):'未配置' }}</template></el-table-column><el-table-column label="启用"><template #default="s"><el-switch :model-value="Boolean(s.row.enabled)" :loading="saving===s.row.id" @change="(v:boolean)=>update(s.row,{enabled:v?1:0})"/></template></el-table-column></el-table></el-card></template><script setup lang="ts">import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import {messageApi} from '@/api';const rows=ref<any[]>([]),loading=ref(false),error=ref(''),saving=ref<number|undefined>();const unwrap=(r:any)=>r?.data??r;async function load(){loading.value=true;error.value='';try{const d:any=unwrap(await messageApi.list());const list=d?.list??d?.items??d?.data??d;rows.value=Array.isArray(list)?list:[]}catch(e:any){rows.value=[];error.value=e?.response?.data?.message||e?.message||'消息配置加载失败'}finally{loading.value=false}}async function update(row:any,payload:any){saving.value=row.id;try{await messageApi.update(row.id,payload);ElMessage.success('配置已保存');await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||e?.message||'保存失败')}finally{saving.value=undefined}}onMounted(load);</script>
